Now I'll create the AppShell component with navigation. I'll need to add Settings and Stats icons to the approved list. Let me create the AppShell component:

<write_to_file>
<path>apps/web/src/components/shared/AppShell.tsx</path>
<content>import { AppBar, Box, Container, IconButton, Toolbar, Typography } from "@mui/material";
import { useLocation, useNavigate } from "react-router-dom";
import SettingsRounded from "@mui/icons-material/SettingsRounded";
import LeaderboardRounded from "@mui/icons-material/LeaderboardRounded";
import SportsEsportsRounded from "@mui/icons-material/SportsEsportsRounded";
import { gameTokens } from "../../theme/tokens";

interface AppShellProps {
  children: React.ReactNode;
}

export const AppShell = ({ children }: AppShellProps) => {
  const navigate = useNavigate();
  const location = useLocation();

  const isActive = (path: string) => location.pathname === path;

  return (
    <Box sx={{ display: "flex", flexDirection: "column", minHeight: "100vh" }}>
      <AppBar position="static" color="default" elevation={0}>
        <Toolbar>
          <Typography variant="h6" component="div" sx={{ flexGrow: 1, fontWeight: 700 }}>
            Snake Game
          </Typography>
          <Box sx={{ display: "flex", gap: 1 }}>
            <IconButton
              aria-label="Game"
              onClick={() => navigate("/")}
              sx={{
                color: isActive("/") ? gameTokens.colors.action : gameTokens.colors.text
              }}
            >
              <SportsEsportsRounded />
            </IconButton>
            <IconButton
              aria-label="Statistics"
              onClick={() => navigate("/stats")}
              sx={{
                color: isActive("/stats") ? gameTokens.colors.action : gameTokens.colors.text
              }}
            >
              <LeaderboardRounded />
            </IconButton>
            <IconButton
              aria-label="Settings"
              onClick={() => navigate("/settings")}
              sx={{
                color: isActive("/settings") ? gameTokens.colors.action : gameTokens.colors.text
              }}
            >
              <SettingsRounded />
            </IconButton>
          </Box>
        </Toolbar>
      </AppBar>
      <Box component="main" sx={{ flexGrow: 1 }}>
        {children}
      </Box>
    </Box>
  );
};
</content>
</write_to_file>

